#include <iostream>
#include <vector>
#include <algorithm>
#include <cstring>
#include <cstdio>
#include <cmath>
#include <cstdlib>
#include <ctime>
#include <queue>
#include <set>
#include <map>
#include <stack>
using namespace std;

typedef long long LL;
const int N=250100;

int getInt() {
    int val=0; bool sign=true; char c=getchar();
    while ((c<'0'||c>'9') && c!='-') c=getchar();
    if (c=='-') { sign=false; c=getchar(); }
    while (c>='0' && c<='9') { val=val*10+c-'0'; c=getchar(); }
    return sign ? val : -val;
}

int mod_value,m;
int sizeArr[N],invArr[N];
struct DataStruct { int a[19]; }fArr[N];

inline int quickPow(int base, int exp) {
    int res=1;
    while (exp) {
        if (exp & 1) res=1LL*res*base%mod_value;
        base=1LL*base*base%mod_value; exp>>=1;
    }
    return res;
}

int main() {
#ifndef ONLINE_JUDGE
    freopen("CF838C.in","r",stdin);
    freopen("CF838C.out","w",stdout);
#endif
    int i, s, n=getInt(), k=getInt(), a, b, y, t[20]={}, p[20]={};
    DataStruct *F, *G;
    mod_value=getInt();

    if (n%2==1) {
        printf("%d\n", quickPow(k, n));
        return 0;
    }

    for (i=0; i<18; i++) m+= (n>>i)&1;

    for (i=0, s=1; i<=n; i++) {
        invArr[i]=i<2 ? 1 : -1LL*(mod_value/i)*invArr[mod_value%i]%mod_value;
        sizeArr[i]=sizeArr[i>>1]+(i&1);
        s=1LL*s*invArr[i]%mod_value;
        if ((i&n)==i)
            fArr[i].a[sizeArr[i]]=s;
    }

    for (i=0; i<18; i++)
        if (n>>i&1)
            for (s=n; s; (--s)&=n)
                if (s>>i&1)
                    for (a=0, F=&fArr[s^(1<<i)], G=&fArr[s]; a<=m; a++) (G->a[a]+=F->a[a])%=mod_value;

    for (i=0; i<=n; i++) if ((i&n)==i) {
        F=&fArr[i];
        for (a=0; a<=m; a++) y[a]=F->a[a], F->a[a]=!a;
        for (b=k; b; b>>=1) {
            if (b&1) {
                for (a=0; a<=m; a++) p[a]=F->a[a], F->a[a]=0;
                for (a=0; a<=m; a++)
                    if (y[a])
                        for (b=0; a+b<=m; b++)
                            F->a[a+b]=(F->a[a+b]+1LL*y[a]*p[b])%mod_value;
            }
            if (b>>=1) {
                for (a=0; a<=m; a++) p[a]=y[a], y[a]=0;
                for (a=0; a<=m; a++)
                    if (p[a])
                        for (b=0; a+b<=m; b++)
                            y[a+b]=(y[a+b]+1LL*p[a]*p[b])%mod_value;
            }
        }
    }

    for (i=0; i<18; i++)
        if (n>>i&1)
            for (s=n; s; (--s)&=n)
                if (s>>i&1)
                    for (a=0, F=&fArr[s^(1<<i)], G=&fArr[s]; a<=m; a++) (G->a[a]-=F->a[a])%=mod_value;

    s=fArr[n].a[m];
    for (i=n; i; i--) s=1LL*s*i%mod_value;
    printf("%d\n", ((quickPow(k, n)-s)%mod_value+mod_value)%mod_value);
    return 0;
}
